#!/usr/bin/env node
/*
 * Builds dist/play.html: the whole game — every map snapshot it ships — as
 * one self-contained page.
 *
 * Everything (CSS, the app scripts, and each snapshot's map data and
 * historical notes) is inlined, so the file can be opened from disk, emailed,
 * or hosted anywhere without the rest of the repo. Used to publish the
 * playable link.
 *
 * Snapshot data files are discovered, not hardcoded: every data/world<year>.js
 * and data/notes<year>.js under data/ is picked up automatically (world files
 * before notes files, each group ordered by year ascending — this matches
 * index.html's load order, so window.GEOMAPS is fully populated before the
 * app scripts run). Adding a new year's data needs no change here.
 *
 * Usage: node tools/bundle.js [--full]
 *   --full  emit a complete <!doctype html> document (default emits a fragment
 *           with <title>, <style>, markup and <script>, for hosts that supply
 *           their own document skeleton).
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');

// Fail loudly and clearly rather than let a raw ENOENT stack trace stand in
// for "the data pipeline hasn't run yet".
const read = (relPath) => {
  const abs = path.join(ROOT, relPath);
  if (!fs.existsSync(abs)) {
    throw new Error(`bundle.js: missing required file "${relPath}" — cannot build dist/play.html without it.`);
  }
  return fs.readFileSync(abs, 'utf8');
};

// A closing script tag inside inlined JS would end the block early. None of the
// current sources contain one, but guard anyway so future data can't break out.
const safe = (js) => js.split('</script').join('<\\/script');

// ---- discover the per-year data files --------------------------------------
// data/world<year>.js and data/notes<year>.js are generated by
// tools/build_data.py, one pair per snapshot year (e.g. 1914, 1940). Glob
// rather than hardcode a year so shipping a new snapshot needs no change here.
function findYearFiles(prefix) {
  const dataDir = path.join(ROOT, 'data');
  const re = new RegExp(`^${prefix}(\\d+)\\.js$`);
  let names;
  try {
    names = fs.readdirSync(dataDir);
  } catch (err) {
    throw new Error(`bundle.js: could not read the data/ directory (${err.message}) — run tools/build_data.py first.`);
  }
  return names
    .map((name) => {
      const m = name.match(re);
      return m ? { file: `data/${name}`, year: Number(m[1]) } : null;
    })
    .filter(Boolean)
    .sort((a, b) => a.year - b.year);
}

const worldFiles = findYearFiles('world');
const notesFiles = findYearFiles('notes');

if (worldFiles.length === 0) {
  throw new Error(
    'bundle.js: no data/world*.js files found — run tools/build_data.py first ' +
    '(e.g. `python3 tools/build_data.py --year all`) to generate the map data.'
  );
}

// Every world snapshot should have been generated alongside a matching notes
// file; a mismatch means the data pipeline run for that year is incomplete.
const notesYears = new Set(notesFiles.map((f) => f.year));
for (const w of worldFiles) {
  if (!notesYears.has(w.year)) {
    throw new Error(
      `bundle.js: data/world${w.year}.js has no matching data/notes${w.year}.js ` +
      `— the ${w.year} data looks incomplete.`
    );
  }
}

const html = read('index.html');
const body = html.match(/<body[^>]*>([\s\S]*?)<\/body>/)[1];
const markup = body
  .replace(/<script\b[\s\S]*?<\/script>/g, '')   // scripts are inlined below
  .trim();

let css = read('css/style.css');

// The published page inherits the viewer's theme, which has three states:
// an explicit light/dark stamp on <html>, or nothing at all (system default).
// The stylesheet defines the full light palette on bare :root and overrides
// tokens under prefers-color-scheme. Guard that override so an explicit light
// choice beats a dark OS, and repeat it for an explicit dark choice.
const darkBlock = css.match(/@media \(prefers-color-scheme: dark\) \{\s*:root \{([\s\S]*?)\n {2}\}/);
if (!darkBlock) throw new Error('could not find the dark-theme token block in css/style.css');
css = css.replace(
  '@media (prefers-color-scheme: dark) {\n  :root {',
  '@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) {'
);
css += `

/* Explicit dark choice wins over a light OS (same tokens as the media query). */
:root[data-theme="dark"] {${darkBlock[1]}
}

/* The host paints its own ground behind the page, so state the background. */
html, body { background: var(--page-bg); }
`;

// World files first (so every year is registered in window.GEOMAPS), then
// notes files, then the app scripts that read them.
const scriptFiles = [
  ...worldFiles.map((f) => f.file),
  ...notesFiles.map((f) => f.file),
  'js/map.js',
  'js/game.js',
  'js/app.js',
];
const scripts = scriptFiles.map((f) => `<script>\n${safe(read(f))}\n</script>`).join('\n');

// Keep head and body content as separate pieces. (Splitting a joined string
// back apart is not safe here: the CSS contains blank lines of its own.)
const head = `<title>World Map Time Machine</title>\n\n<style>\n${css}\n</style>`;
const bodyOut = `${markup}\n\n${scripts}`;

const full = process.argv.includes('--full');
const out = full
  ? '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n' +
    '<meta name="viewport" content="width=device-width, initial-scale=1">\n' +
    `${head}\n</head>\n<body>\n${bodyOut}\n</body>\n</html>\n`
  : `${head}\n\n${bodyOut}\n`;

fs.mkdirSync(path.join(ROOT, 'dist'), { recursive: true });
const dest = path.join(ROOT, 'dist', 'play.html');
fs.writeFileSync(dest, out);
console.log(`wrote dist/play.html — ${(out.length / 1024).toFixed(0)} KB, ` +
  `${full ? 'full document' : 'fragment'}, years ${worldFiles.map((f) => f.year).join('/')}`);
